-- Sensor dashboard PostgreSQL schema and seed data
BEGIN;
DROP TABLE IF EXISTS measurements CASCADE;
DROP TABLE IF EXISTS sensor_categories CASCADE;
DROP TABLE IF EXISTS sensors CASCADE;
DROP TABLE IF EXISTS measurement_categories CASCADE;
DROP TABLE IF EXISTS users CASCADE;

CREATE TABLE users (
    id SERIAL PRIMARY KEY,
    username VARCHAR(80) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    full_name VARCHAR(160) NOT NULL,
    email VARCHAR(255) NOT NULL UNIQUE,
    role VARCHAR(20) NOT NULL DEFAULT 'user',
    is_active BOOLEAN NOT NULL DEFAULT TRUE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE measurement_categories (
    id SERIAL PRIMARY KEY,
    code VARCHAR(40) NOT NULL UNIQUE,
    name VARCHAR(100) NOT NULL,
    unit VARCHAR(20) NOT NULL
);

CREATE TABLE sensors (
    id SERIAL PRIMARY KEY,
    identifier VARCHAR(80) NOT NULL UNIQUE,
    name VARCHAR(160) NOT NULL,
    description TEXT NOT NULL DEFAULT '',
    location VARCHAR(160) NOT NULL DEFAULT '',
    status VARCHAR(30) NOT NULL DEFAULT 'active',
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE TABLE sensor_categories (
    sensor_id INTEGER NOT NULL REFERENCES sensors(id) ON DELETE CASCADE,
    category_id INTEGER NOT NULL REFERENCES measurement_categories(id) ON DELETE CASCADE,
    PRIMARY KEY (sensor_id, category_id)
);

CREATE TABLE measurements (
    id SERIAL PRIMARY KEY,
    sensor_id INTEGER NOT NULL REFERENCES sensors(id) ON DELETE CASCADE,
    category_id INTEGER NOT NULL REFERENCES measurement_categories(id),
    value NUMERIC(10, 2) NOT NULL,
    recorded_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX ix_users_username ON users(username);
CREATE INDEX ix_users_email ON users(email);
CREATE INDEX ix_measurement_categories_code ON measurement_categories(code);
CREATE INDEX ix_sensors_identifier ON sensors(identifier);
CREATE INDEX ix_measurements_sensor_id ON measurements(sensor_id);
CREATE INDEX ix_measurements_category_id ON measurements(category_id);
CREATE INDEX ix_measurements_recorded_at ON measurements(recorded_at);

SELECT setval('users_id_seq', (SELECT MAX(id) FROM users));
SELECT setval('measurement_categories_id_seq', (SELECT MAX(id) FROM measurement_categories));
SELECT setval('sensors_id_seq', (SELECT MAX(id) FROM sensors));
SELECT setval('measurements_id_seq', (SELECT MAX(id) FROM measurements));
COMMIT;
